def handler(event: dict, context) -> dict:
    """Отдаёт отчёт о создании программного обеспечения в формате Word."""
    if event.get('httpMethod') == 'OPTIONS':
        return {
            'statusCode': 200,
            'headers': {**CORS, 'Access-Control-Max-Age': '86400'},
            'isBase64Encoded': False,
            'body': '',
        }

    return {
        'statusCode': 200,
        'headers': {
            **CORS,
            'Content-Type': DOCX,
            'Content-Disposition': 'attachment; filename="otchet-inspektor.docx"',
            'Cache-Control': 'no-cache',
        },
        'isBase64Encoded': True,
        'body': DATA,
    }
